import{_ as a,o as n,c as i,a2 as s}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Skills and knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/skills-and-knowledge.md","filePath":"game-design/skills-and-knowledge.md"}'),r={name:"game-design/skills-and-knowledge.md"};function o(t,e,l,d,c,g){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="skills-and-knowledge" tabindex="-1">Skills and knowledge <a class="header-anchor" href="#skills-and-knowledge" aria-label="Permalink to &quot;Skills and knowledge&quot;">​</a></h1><p><strong>Design status: Accepted division of roles; Experimental Stage 2A Anatomy disclosure approved 2026-10-02; broader knowledge policies Proposed. Implementation: legacy skills plus qualitative Anatomy inspection.</strong></p><p>Anatomy informs <strong>where</strong>: body structure and condition. Arms Lore informs <strong>how/with what</strong>: equipment, protection and vulnerabilities. Tactics informs <strong>when</strong>: opportunities and tactical understanding. Weapon skill informs <strong>execution</strong>. Player choices should matter alongside character investment.</p><p>A roughly 700-point skill-cap foundation expresses opportunity cost, not an instruction to change current configuration. Exact checks, training, disclosure precision, thresholds and tradeoffs are unfinished.</p><p>Stage 2A adds localized information to the existing Anatomy skill. The experimental rule approved on 2026-10-02 retains the existing Anatomy skill check over a 0–100 range and its gain/cooldown behavior: success reveals all seven qualitative conditions; failure reveals no local state. No exact integrity, trauma, armor numbers or aiming probabilities are disclosed by Anatomy. Existing strength/dexterity/stamina information remains unchanged. The experiment applies only in UOR when active, to living connected untransformed human players within eight tiles, visible and in LOS. Tactics remains unchanged until tactical opportunities exist.</p><p>Privileged testing information is separate from character knowledge: it does not consume, train or require Anatomy, and does not broaden what the skill reveals.</p><p><strong>Gap:</strong> final disclosure precision/progression, Arms Lore and Tactics systems, and live readability remain unvalidated. The Stage 2A rule is disposable prototype policy, not final balance. Assessment contract · Open questions.</p><h2 id="proposed-magic-roles" tabindex="-1">Proposed magic roles <a class="header-anchor" href="#proposed-magic-roles" aria-label="Permalink to &quot;Proposed magic roles&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/magic.html">Magic redesign v0.1</a> separates Magery execution, permanent spell knowledge, Mastery, institutional learning, Inscription engineering and Meditation/concentration. It preserves classless hybrids rather than adding a skill for every discipline/affinity. Its <a href="/Syrolands-Public/game-design/magic.html#use-based-gain-and-structured-teaching">training targets</a> and <a href="/Syrolands-Public/game-design/magic.html#normal-and-focused-cast">Anatomy-based focused casting</a> remain Proposed; they do not change the approved Stage 2A Anatomy disclosure rule or current skill configuration.</p><h2 id="proposed-environmental-expertise" tabindex="-1">Proposed environmental expertise <a class="header-anchor" href="#proposed-environmental-expertise" aria-label="Permalink to &quot;Proposed environmental expertise&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/living-world.html#knowledge-professions-and-traces">living-world proposal</a> gives Lumberjacking, Mining, Tracking, Camping and Magery possible roles in material interaction and qualitative environmental knowledge. Disclosure rules and potential new professions remain unresolved; no skills, caps or existing Anatomy policies change here.</p><h2 id="proposed-profession-progression-and-techniques" tabindex="-1">Proposed profession progression and techniques <a class="header-anchor" href="#proposed-profession-progression-and-techniques" aria-label="Permalink to &quot;Proposed profession progression and techniques&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">character skill framework</a> now centralizes cap/gain, useful low-skill capability and teaching; <a href="/Syrolands-Public/game-design/characters/progression.html">character progression</a> owns the general philosophy, and <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html">techniques</a> owns learned specialization. <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a> retains craft journals, production and reputation. All new ranges, gain, teaching and creation rules remain <strong>Proposed</strong>; current configuration and approved Anatomy behavior are unchanged.</p><p>Skill, learned technique, profession path and world identity are distinct. <a href="/Syrolands-Public/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking / Fletching</a> is proposed as a Carpentry/Archery technique path with optional supporting crafts, not a standalone skill. This page is a role summary, <strong>not a reconciled exhaustive skill list</strong>. No skill removal, ID reassignment or character migration is approved. The <a href="/Syrolands-Public/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">reconciliation register</a> records the roster gap and the earlier optional Forestry/Geology/Engineering candidates.</p><h2 id="batch-02-character-framework" tabindex="-1">Batch 02 character framework <a class="header-anchor" href="#batch-02-character-framework" aria-label="Permalink to &quot;Batch 02 character framework&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/characters/character-creation.html">Backgrounds</a> propose starting histories without permanent classes. <a href="/Syrolands-Public/game-design/characters/stats.html">Stats</a> proposes baseline responsiveness and bounded stat support. Legacy Bowcraft and cap/gain/creation behavior still require reconciliation. Review Anatomy, Tactics and Healing investment pressure in future combat design; the existing roles and approved disclosure remain intact.</p><h2 id="batch-03-combat-skill-review" tabindex="-1">Batch 03 combat skill review <a class="header-anchor" href="#batch-03-combat-skill-review" aria-label="Permalink to &quot;Batch 03 combat skill review&quot;">​</a></h2><p><strong>Proposed:</strong> extend Anatomy as useful interpretation of local trauma and vulnerable regions, with possible Healing and hunting/skinning synergies. This does not change the accepted scoped disclosure above. <a href="/Syrolands-Public/game-design/combat/targeting.html#proposed-targeting-factors-and-knowledge">Targeting</a> owns the proposed targeting factors.</p><p>Tactics remains a martial skill whose role needs review beyond a universally mandatory flat damage contribution: attack decisions, stance/positioning, advanced techniques and tactical execution are candidate uses. Inherited damage scaling is not the final redesign. <a href="/Syrolands-Public/game-design/combat/overview.html#combat-foundation-integration">Build diversity</a> and <a href="/Syrolands-Public/game-design/combat/damage.html#proposed-injuries-and-healing">Healing boundaries</a> remain proposals, with no new mandatory skill bundle.</p>',19)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
